    padding-top: 10px;
}
.ak_search-section .ak_search-card .con-block a{
    text-decoration: none;
    color: #3a3a3a;
}
.ann_collabs .elementor-container{
    /* max-width: 1200px; */
    margin: auto;
}

.ak_search-section  .con-block a::before{
    position: absolute;
    content: " ";
    cursor: pointer;
    inset: 0;
}

.ak-wish_icon {
    position: absolute;
    top: 10px;
    right: 10px;
    width: 40px;
    background: #fff;
    text-align: center;
    border-radius: 30px;
    padding: 10px;
    height: 40px;
    font-size: 16px;
    color: #E98C9A;
    z-index: 9;
    cursor: pointer;
}



.ak-wish-warp .tooltip {
    background: #3a3a3a;
    bottom: 100%;
    color: #fff;
    display: block;
    left: 50%;
    margin-bottom: 15px;
    font-size: 14px !important;
    opacity: 0;
    padding: 5px;
    pointer-events: none;
    position: absolute;
    width: auto;
    transform: translate(-50%, 10px);
    transition: all .25s ease-out;
    box-shadow: 2px 2px 6px rgba(0, 0, 0, 0.28);
    white-space: nowrap;
    border-radius: 5px;
    
}

.ak-wish-warp  .tooltip:before {
    bottom: -20px;
    content: " ";
    display: block;
    height: 20px;
    left: 0;
    position: absolute;
    width: 100%;
}

.ak-wish-warp  .tooltip:after {
    border-left: solid transparent 10px;
    border-right: solid transparent 10px;
    border-top: solid #3a3a3a 10px;
    bottom: -10px;content: " ";
    height: 0;
    left: 50%
    ;margin-left: -13px;
    position: absolute;
    width: 0;}

.ak-wish_icon:hover .tooltip {
    opacity: 1;
    pointer-events: auto;
    transform: translate(-50%, 0px);
}


.ak-wish-warp {
    position: relative;
    cursor: pointer;
}

/* Search Recipes Page */
.ak_search-section .pagination .page-numbers {
    display: flex;
    font-weight: 600;
    align-items: center;
    justify-content: center;
    padding: 4px 4px;
    line-height: normal;
    transition: all ease-in-out 0.5s;
}
.ak_search-section  .pagination .page-numbers.current,
.ak_search-section  .pagination .page-numbers:hover{
    color: #e98c9a;
}

.ak_search-section .pagination{
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
}

.ak_search-section .ak_search-card .con-block h3{
    font-size: 20px;
    font-family: normal;
}

.ak_search-section .ak_search-card  .img-div {
    position: relative;
    height: 100%;
    width: 100%;
    padding-top: 100%;
}

.ak_search-section .ak_search-card img{
    position: absolute;
    top:0;
    left: 0;
    height: 100%;
    width: 100%;
    object-fit: cover;
    right: 0;
    bottom: 0;
}

.ak__recipe--container .radio--design span {
    border: 0 !important;
}


